module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output reg zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);

    reg [32:0] res;

    // Zero detection
    assign zero = (res == 32'b0);

    // Carry detection
    assign carry = (aluc == 6'b100000 || aluc == 6'b100001 || aluc == 6'b100010 || aluc == 6'b100011) && (res[32] != 0);

    // Overflow detection
    assign overflow = ((aluc == 6'b100000) && (~a[31] & ~b[31] & res[32])) ||
                      ((aluc == 6'b100010) && (a[31] & ~b[31] & ~res[32]));

    // Negative detection
    assign negative = res[31];

    // Flag detection
    assign flag = (aluc == 6'b101010 || aluc == 6'b101011) && (res[31] != (res >> 1)[31]);

    // Result assignment
    always @(*) begin
        case (aluc)
            6'b000000: res = {1'b0, a << b[4:0]}; // SLL
            6'b000010: res = {1'b0, a >> b[4:0]}; // SRL
            6'b000011: res = {1'b0, $signed(a) >>> b[4:0]}; // SRA
            6'b000100: res = {1'b0, a << b[4:0]}; // SLLV
            6'b000110: res = {1'b0, a >> b[4:0]}; // SRLV
            6'b000111: res = {1'b0, $signed(a) >>> b[4:0]}; // SRAV
            6'b100000: res = a + b; // ADD
            6'b100001: res = a + b; // ADDU
            6'b100010: res = a - b; // SUB
            6'b100011: res = a - b; // SUBU
            6'b100100: res = a & b; // AND
            6'b100101: res = a | b; // OR
            6'b100110: res = a ^ b; // XOR
            6'b100111: res = ~(a | b); // NOR
            6'b101010: res = $signed(a) < $signed(b); // SLT
            6'b101011: res = a < b; // SLTU
            6'b001111: res = {16'b0, a}; // LUI
            default: res = 33'b0;
        endcase
    end

    // Assigning result to output
    assign r = res[31:0];

endmodule
